'use client';

import { useEffect, useState } from 'react';
import { apiRequest, adminEvents, deleteEvent, deletePerson, getAlumni, getEvent, getEvents, logout, refreshSession, rsvp, updateProfile } from '../services/api';
import AdminScreen from '../components/AdminScreen';
import DirectoryScreen from '../components/DirectoryScreen';
import EventsScreen from '../components/EventsScreen';
import EventDetailScreen from '../components/EventDetailScreen';
import Overview from '../components/Overview';
import ProfileScreen from '../components/ProfileScreen';
import Shell from '../components/Shell';

const tabs = [['Overview', '◒'], ['Alumni directory', '◌'], ['Events', '▣'], ['My profile', '◉']];

function timeGreeting() {
  const hour = new Date().getHours();
  if (hour < 12) return 'Good morning';
  if (hour < 17) return 'Good afternoon';
  return 'Good evening';
}

function todayLabel() {
  return new Intl.DateTimeFormat('en', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date()).toUpperCase();
}

export default function Home() {
  const [active, setActive] = useState('Overview');
  const [query, setQuery] = useState('');
  const [people, setPeople] = useState([]);
  const [events, setEvents] = useState([]);
  const [registered, setRegistered] = useState([]);
  const [user, setUser] = useState({ name: 'Member' });
  const [loading, setLoading] = useState(true);
  const [selectedEvent, setSelectedEvent] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        let profile;
        try { profile = await apiRequest('/auth/profile/'); } catch { await refreshSession(); profile = await apiRequest('/auth/profile/'); }
        setUser(profile);
        const [peopleData, eventsData, mine] = await Promise.all([getAlumni(), getEvents(), apiRequest('/my-events/')]);
        setPeople(peopleData.results.filter((item) => item.role !== 'super_admin'));
        setEvents(eventsData.results);
        setRegistered(mine.results.filter((item) => item.status === 'registered').map((item) => item.event_id));
      } catch { window.location.assign('/login'); } finally { setLoading(false); }
    })();
  }, []);

  async function saveProfile(profile) { setUser(await updateProfile(profile)); }
  async function openEvent(event) { try { setSelectedEvent(await getEvent(event.id)); } catch { setSelectedEvent(event); } }
  async function registerFor(event) { setSelectedEvent(event); try { await rsvp(event.id); setRegistered((current) => current.includes(event.id) ? current : [...current, event.id]); setSelectedEvent((current) => current ? { ...current, is_registered: true, participant_count: (current.participant_count || 0) + 1, remaining_capacity: Math.max(0, (current.remaining_capacity ?? current.capacity ?? 100) - 1) } : current); } catch (error) { if (error.message.includes('Authentication')) window.location.assign('/login'); } }
  async function createEvent(event) { const created = await adminEvents(event); setEvents((current) => [created, ...current]); }
  async function removeEvent(id) { await deleteEvent(id); setEvents((current) => current.filter((event) => event.id !== id)); }
  async function removePerson(id) { await deletePerson(id); setPeople((current) => current.filter((person) => person.user_id !== id && person.id !== id)); }

  const admin = user.role === 'admin' || user.role === 'super_admin';
  const navTabs = admin ? [...tabs, ['Admin console', '◆']] : tabs;
  const title = active === 'Overview' ? `${timeGreeting()}, ${user.name?.split(' ')[0] || 'there'}` : active;
  let screen;
  if (selectedEvent) screen = <EventDetailScreen event={selectedEvent} registered={registered.includes(selectedEvent.id)} onRsvp={registerFor} onBack={() => setSelectedEvent(null)} />;
  else if (active === 'Overview') screen = <Overview events={events} people={people} registered={registered} onRsvp={registerFor} onOpen={openEvent} setActive={setActive} />;
  if (!selectedEvent && active === 'Events') screen = <EventsScreen events={events} registered={registered} onRsvp={registerFor} onOpen={openEvent} />;
  if (!selectedEvent && active === 'Alumni directory') screen = <DirectoryScreen people={people} query={query} setQuery={setQuery} />;
  if (!selectedEvent && active === 'My profile') screen = <ProfileScreen user={user} onSave={saveProfile} />;
  if (!selectedEvent && active === 'Admin console' && admin) screen = <AdminScreen events={events} people={people} onCreateEvent={createEvent} onDeleteEvent={removeEvent} onDeletePerson={removePerson} />;

  return <Shell user={user} admin={admin} active={active} setActive={setActive} navTabs={navTabs} onSignOut={async () => { await logout(); window.location.assign('/login'); }}><section className="content"><header className="topbar"><div><p className="kicker">{todayLabel()}</p><h1>{title}</h1></div><div className="top-actions"><span className="role-pill">{admin ? 'ADMIN' : 'MEMBER'}</span><span className="avatar avatar-small">{user.name?.slice(0, 2).toUpperCase()}</span></div></header>{screen}{loading && <div className="loading-state" role="status" aria-live="polite"><span className="loading-line" /><span className="loading-line short" /><span className="loading-card" /></div>}</section></Shell>;
}
