import { useState } from 'react';

export default function Shell({ children, user, admin, active, setActive, navTabs, onSignOut }) {
    const initials = (user.name || '').split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();
    const [menuOpen, setMenuOpen] = useState(false);
    function selectTab(item) { setActive(item); setMenuOpen(false); }
    return <main className="shell"><aside className={menuOpen ? 'sidebar menu-open' : 'sidebar'}><div className="mobile-nav-header"><div className="brand"><span className="brand-mark">AM</span><span>Alumni<br /><strong>Meet</strong></span></div><button type="button" className="menu-button" onClick={() => setMenuOpen((open) => !open)} aria-expanded={menuOpen} aria-label={menuOpen ? 'Close menu' : 'Open menu'}><span aria-hidden="true">{menuOpen ? '×' : '☰'}</span></button></div><div className="desktop-brand brand"><span className="brand-mark">AM</span><span>Alumni<br /><strong>Meet</strong></span></div><p className="eyebrow">YOUR COMMUNITY</p><nav aria-label="Main navigation">{navTabs.map(([item, icon]) => <button type="button" key={item} className={active === item ? 'nav-item active' : 'nav-item'} onClick={() => selectTab(item)} aria-current={active === item ? 'page' : undefined}><span className="nav-icon" aria-hidden="true">{icon}</span>{item}</button>)}</nav><div className="sidebar-bottom"><div className="profile-mini"><span className="avatar avatar-small">{initials}</span><span><strong>{user.name}</strong><small>{admin ? 'Administrator' : `Class of ${user.batch_year || '—'}`}</small></span></div><button type="button" className="sign-out" onClick={onSignOut}>↪ Sign out</button></div></aside>{children}</main>;
}
