import { useState } from 'react';

function initials(name = '') { return name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase(); }

export default function ProfileScreen({ user, onSave }) {
  const [form, setForm] = useState({ name: user.name || '', batch_year: user.batch_year || '', current_company: user.current_company || '', job_title: user.job_title || '', location: user.location || '', bio: user.bio || '' });
  const [saved, setSaved] = useState(false);
  async function submit(event) { event.preventDefault(); await onSave({ ...form, batch_year: form.batch_year ? Number(form.batch_year) : undefined }); setSaved(true); }
  return <div className="profile-screen"><div className="screen-heading"><div><span className="section-kicker">YOUR STORY</span><h2>My profile</h2><p>Keep your details current so classmates can find you.</p></div><div className="avatar avatar-profile">{initials(form.name)}</div></div><form className="profile-form" onSubmit={submit}><label>Full name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Batch year<input type="number" value={form.batch_year} onChange={(event) => setForm({ ...form, batch_year: event.target.value })} /></label><label>Current company<input value={form.current_company} onChange={(event) => setForm({ ...form, current_company: event.target.value })} /></label><label>Job title<input value={form.job_title} onChange={(event) => setForm({ ...form, job_title: event.target.value })} /></label><label>Location<input value={form.location} onChange={(event) => setForm({ ...form, location: event.target.value })} /></label><label className="wide-field">Bio<textarea value={form.bio} onChange={(event) => setForm({ ...form, bio: event.target.value })} rows="4" /></label><div className="form-footer"><button className="primary-button">Save profile</button>{saved && <span className="saved-note">Profile updated</span>}</div></form></div>;
}
