import { useMemo } from 'react';

function initials(name = '') { return name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase(); }

export default function DirectoryScreen({ people, query, setQuery }) {
  const filtered = useMemo(() => people.filter((person) => `${person.name} ${person.current_company} ${person.batch_year} ${person.location}`.toLowerCase().includes(query.toLowerCase())), [people, query]);
  return <><div className="screen-heading"><div><span className="section-kicker">THE COMMUNITY</span><h2>Find your people</h2><p>Browse alumni by name, batch, workplace, or city.</p></div><label className="search"><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search people" /></label></div><div className="alumni-grid directory-grid">{filtered.map((person) => <article className="alumni-card" key={person.id || person.name}><div className="avatar avatar-large teal">{initials(person.name)}</div><h3>{person.name}</h3><p>{person.job_title || 'Alumni member'}{person.current_company ? <> at <strong>{person.current_company}</strong></> : null}</p><div className="person-meta"><span>Class of {person.batch_year || '—'}</span><span>{person.location || 'India'}</span></div><button className="connect-button">View profile ↗</button></article>)}</div>{!filtered.length && <div className="empty-state">No alumni match your search.</div>}</>;
}
